{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Ensure PubSub Topics are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The PubSub topic is not encrypted with a Customer Supplied Encryption Key (CSEK), potentially exposing sensitive data to unauthorized access."
    }
  ],
  "patched_code": "resource "google_pubsub_topic" "notification_queue" {
  name = "insurance-claims-processing-platform-pubsub-notifications"
  labels = {
    environment = "production"
    component   = "notifications"
  }
  kms_key_name = google_kms_crypto_key.pubsub_key.id
}

resource "google_kms_key_ring" "pubsub_key_ring" {
  name     = "insurance-claims-processing-platform-pubsub-key-ring"
  location = "global"
}

resource "google_kms_crypto_key" "pubsub_key" {
  name            = "insurance-claims-processing-platform-pubsub-key"
  key_ring        = google_kms_key_ring.pubsub_key_ring.id
  rotation_period = "100000s"
}",
  "fix_summary": "Added a Customer Supplied Encryption Key (CSEK) to the PubSub topic using Google Cloud KMS, creating a key ring and crypto key for encryption."
}
